import { useCallback } from 'react';
import { useAppContext } from '../components/logical/AppContext';
import { LogParser } from '../components/logical/LogParser';
export function useFileProcessor() {
    const { actions } = useAppContext();
    const processFile = useCallback(async (file) => {
        actions.setProcessing(true);
        actions.clearError();
        try {
            const content = await file.text();
            const parsedData = LogParser.parseLogContent(content);
            actions.setLogData(parsedData);
        }
        catch (error) {
            const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
            actions.setError(`Failed to process file: ${errorMessage}`);
        }
    }, [actions]);
    return { processFile };
}
