export function filterSessions(sessions, filter) {
    switch (filter) {
        case 'all':
            return sessions;
        case 'ended-successfully':
            return sessions.filter(session => {
                const hasEnded = session.events.some(e => e.status === 'ended');
                const hasBadRequests = session.events.some(e => typeof e.status === 'number' && e.status >= 400);
                return hasEnded && !hasBadRequests;
            });
        case 'not-ended':
            return sessions.filter(session => !session.events.some(e => e.status === 'ended'));
        case 'bad-requests':
            return sessions.filter(session => session.events.some(e => typeof e.status === 'number' && e.status >= 400));
        default:
            return sessions;
    }
}
export function getFilterCounts(sessions) {
    return {
        all: sessions.length,
        'ended-successfully': filterSessions(sessions, 'ended-successfully').length,
        'not-ended': filterSessions(sessions, 'not-ended').length,
        'bad-requests': filterSessions(sessions, 'bad-requests').length
    };
}
export function getFilterDescription(filter) {
    switch (filter) {
        case 'all':
            return 'All sessions in the log';
        case 'ended-successfully':
            return 'Sessions that completed successfully (ended without 4xx/5xx errors)';
        case 'not-ended':
            return 'Sessions that were created but never reached completion';
        case 'bad-requests':
            return 'Sessions that encountered 4xx or 5xx HTTP errors';
        default:
            return '';
    }
}
