import { LogParser } from '../components/logical/LogParser';
import { filterSessions, getFilterCounts } from './sessionFilters';
// This utility can be used to test the LogParser in the browser console
export function testLogParserWithSampleData() {
    const sampleLogContent = `2025-07-23T14:37:09.791Z [INFO] Running with 5 concurrent tabs
2025-07-23T14:37:10.123Z [INFO] testConcurrency: 3
2025-07-23T14:37:11.456Z [INFO] Using puppeteer for browser automation
2025-07-23T14:37:12.789Z [REQUEST] POST "/api/sessions/123456789012345678901/started-status" respond with Created(201)
2025-07-23T14:37:13.012Z [REQUEST] POST "/api/sessions/987654321098765432109/started-status" respond with Bad Request(400)
2025-07-23T14:37:14.345Z [REQUEST] POST "/api/sessions/123456789012345678901/matchandend" respond with OK(200)
2025-07-23T14:37:15.678Z [REQUEST] DELETE "/api/sessions/555666777888999000111?aborted=true" respond with OK(200)
2025-07-23T14:37:16.901Z [REQUEST] POST "/api/sessions/444555666777888999000/started-status" respond with Internal Server Error(500)
2025-07-23T14:37:17.234Z [REQUEST] POST "/api/sessions/333444555666777888999/started-status" respond with Created(201)
2025-07-23T14:37:18.567Z [REQUEST] POST "/api/sessions/333444555666777888999/matchandend" respond with OK(200)`;
    const result = LogParser.parseLogContent(sampleLogContent);
    console.log('=== LogParser Test Results ===');
    console.log('Metadata:', result.metadata);
    console.log('Sessions found:', result.sessions.length);
    console.log('Global time bounds:', result.globalTimeBounds);
    console.log('\n=== Session Details ===');
    result.sessions.forEach((session, index) => {
        console.log(`Session ${index + 1}: ${session.id}`);
        console.log('  Events:', session.events.map(e => `${e.label}(${e.status})`).join(', '));
        console.log('  Time bounds:', session.timeBounds);
    });
    console.log('\n=== Filter Testing ===');
    const filterCounts = getFilterCounts(result.sessions);
    console.log('Filter counts:', filterCounts);
    console.log('\nEnded Successfully:', filterSessions(result.sessions, 'ended-successfully').map(s => s.id));
    console.log('Not Ended:', filterSessions(result.sessions, 'not-ended').map(s => s.id));
    console.log('Bad Requests:', filterSessions(result.sessions, 'bad-requests').map(s => s.id));
    // Verify expected results
    const expected = {
        product: 'puppeteer',
        browserTabs: 5,
        testConcurrency: 3,
        sessionCount: 5,
        createdSessions: 2,
        errorSessions: 2,
        endedSessions: 2,
        abortedSessions: 1
    };
    const actual = {
        product: result.metadata.product,
        browserTabs: result.metadata.browserTabs,
        testConcurrency: result.metadata.testConcurrency,
        sessionCount: result.metadata.sessionCount,
        createdSessions: result.sessions.filter(s => s.events.some(e => e.status === 201)).length,
        errorSessions: result.sessions.filter(s => s.events.some(e => typeof e.status === 'number' && e.status >= 400)).length,
        endedSessions: result.sessions.filter(s => s.events.some(e => e.status === 'ended')).length,
        abortedSessions: result.sessions.filter(s => s.events.some(e => e.status === 'aborted')).length,
    };
    console.log('\n=== Validation Results ===');
    console.log('Expected:', expected);
    console.log('Actual:', actual);
    const isValid = JSON.stringify(expected) === JSON.stringify(actual);
    console.log('✅ Test Result:', isValid ? 'PASSED' : 'FAILED');
    return { result, expected, actual, isValid };
}
// Make it available globally for browser testing
if (typeof window !== 'undefined') {
    window.testLogParserWithSampleData = testLogParserWithSampleData;
}
